mapper.select:
select t.device_code as deviceCode, GROUP_CONCAT(t.id) as orgRelId, GROUP_CONCAT(t.DEPT_ID) as orgCode,
GROUP_CONCAT(org.DEPT_NAME) as orgName
from vm_organ_device_rel_t t LEFT JOIN sys_dept org ON org.DEPT_ID = t.DEPT_ID
where
t.delete_flag = '0'
and t.device_type = #{deviceType} and org.DEL_FLAG='0' and org.`STATUS` = '0'
and t.TENANT_ID = org.tenant_id


        and t.device_code in

            #{item}



        and t.device_code = #{deviceCode}



    and t.tenant_id = #{tenantId}


    and t.dept_id = #{orgCode}


    and t.industry_code = #{industryCode}

group by t.device_code

select rel.device_code,
       rel.device_name
    from vm_tenant_device_common_rel_t rel
    where rel.device_code = #{param.deviceCode}
          and rel.tenant_id = #{param.tenantId}
          and rel.industry_code = #{param.industryCode}
          and rel.device_type = #{param.deviceType}
          and rel.delete_flag = '0'

mapper.update:
update vm_tenant_device_common_rel_t
   set device_name = #{param.deviceName},
       modifier = #{param.modifier},
       update_time = now()
    where
          device_code = #{param.deviceCode}
      and tenant_id = #{param.tenantId}
      and industry_code = #{param.industryCode}
      and device_type = #{param.deviceType}
      and delete_flag = '0'

mapper.select:
select t.id, t.tenant_id, t.dept_id, t.device_code, d.dept_name,t.industry_code
from vm_organ_device_rel_t t left join sys_dept d on t.dept_id = d.dept_id and d.del_flag='0'
where t.delete_flag='0'
and t.tenant_id = #{param.tenantId}

    and t.industry_code = #{param.industryCode}


    and t.device_code like CONCAT('%', #{param.deviceCode}, '%')


    and t.device_type = #{param.deviceType}

select t.device_code, (case when length(IFNULL(rel.device_name, '')) = 0 then t.device_name else rel.device_name end ) name, t.location, ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')), ST_GeomFromText(CONCAT('POINT(',t.longitude,' ',t.latitude,')')) ) as distance, t.manufacturer_code modelCode, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'uav_manufacturer' AND DICT_VALUE = t.manufacturer_code limit 1) modelName,
case when IFNULL(dct.user_device_coll_id, 0) = 0 then '0' else '1' end isMonitor,
t.longitude, t.latitude, t.device_status, t.access_node, nest.device_code uavNestCode, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName, nest.resource_status uavNestStatus from vm_order_uav_devices o inner join vm_uav_device_info_t t on t.device_code = o.device_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = o.device_code and rel.tenant_id = o.tenant_id and rel.industry_code = o.industry_code and rel.delete_flag = 0 and rel.device_type = 1 left join `vm_uav_nest_device_info` nest on t.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t nrel on nrel.device_code = nest.device_code and nrel.industry_code = o.industry_code and nrel.tenant_id = o.tenant_id and nrel.delete_flag = '0' and nrel.device_type = 4
LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = t.device_code AND dct.coll_obj_type = '11' AND dct.user_id = #{param.userId}
where o.delete_flag = '0' and t.delete_flag = '0' and o.ord_status in (0,1,2)
and ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')), ST_GeomFromText(CONCAT('POINT(',t.longitude,' ',t.latitude,')')) ) <= #{param.radius}
${param.dataScope} group by t.device_code order by t.id
limit #{param.limitSize}

SELECT DISTINCT m.device_code as deviceCode, m.device_status, m.access_node, m.device_name, m.province_code as provinceId,pro.area_name as provinceName,m.city_code as cityId, city.area_name as cityName,m.county_code as countyId,county.area_name as countyName, m.town_code as townCode, town.area_name as townName, m.site_code, m.longitude,m.latitude, 'false' AS checked, '1' AS proLevel, '2' AS cityLevel,'3' AS countryLevel,'4' AS devLevel, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
case when IFNULL(art.id,0) = 0 then '0' else '1' end tagCollect,
(case when length(IFNULL(rel.device_name, '')) = 0 then m.device_name else rel.device_name end ) deviceAlias, nest.device_code uavNestCode, nest.altitude, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName, nest.resource_status uavNestStatus, nest.position_fix uavNestPositionFix, nest.calibration_status uavNestCalibrationStatus FROM vm_order_uav_devices ord LEFT JOIN vm_uav_device_info_t m on m.device_code = ord.device_code LEFT JOIN sys_area pro on pro.area_code = m.province_code LEFT JOIN sys_area city on city.area_code = m.city_code LEFT JOIN sys_area county on county.area_code = m.county_code LEFT JOIN sys_area town on town.area_code = m.town_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = m.device_code and rel.tenant_id = ord.tenant_id and rel.industry_code = ord.industry_code and rel.delete_flag = '0' and rel.device_type = 1 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '11' AND dct.user_id = #{param.userId} left join `vm_uav_nest_device_info` nest on m.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t nrel on nrel.device_code = nest.device_code and nrel.industry_code = ord.industry_code and nrel.tenant_id = ord.tenant_id and nrel.delete_flag = '0' and nrel.device_type = 4
LEFT JOIN vm_ar_tags_tree_user_rel art on art.coll_obj_code = m.device_code and art.coll_obj_type = '11' and art.user_id = #{param.userId}
WHERE m.delete_flag= '0' and ord.ord_status in (0, 1, 2) and ord.delete_flag= '0'
and ord.industry_code = #{param.industryCode}
and ord.tenant_id = #{param.tenantId}
and m.device_status != 2
and dct.user_device_coll_id IS NOT NULL
and m.device_type in
#{type}
and art.coll_obj_code IS NOT NULL
and m.device_code in
#{item}
and m.device_status = #{param.deviceStatus}
and m.device_status in
#{item}
and m.uav_nest_code like CONCAT('%', #{param.uavNestCode}, '%')
and m.camera_model_code = #{param.cameraModelCode}
and m.uav_nest_code in
#{item}
${param.dataScope} ORDER BY m.province_code, m.city_code, m.county_code, m.town_code, m.device_code

SELECT DISTINCT m.device_code as deviceCode, m.device_status, m.access_node, m.device_name, m.province_code as provinceId,pro.area_name as provinceName,m.city_code as cityId, city.area_name as cityName,m.county_code as countyId,county.area_name as countyName, m.town_code as townCode, town.area_name as townName, m.site_code, m.longitude,m.latitude, 'false' AS checked, '1' AS proLevel, '2' AS cityLevel,'3' AS countryLevel,'4' AS devLevel, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor, 'false' isNestDevice,
case when IFNULL(art.id,0) = 0 then '0' else '1' end tagCollect,
(case when length(IFNULL(rel.device_name, '')) = 0 then m.device_name else rel.device_name end ) deviceAlias, nest.device_code uavNestCode, nest.altitude, nest.model_code deviceModelCode, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName, nest.resource_status uavNestStatus, nest.position_fix uavNestPositionFix, nest.calibration_status uavNestCalibrationStatus FROM vm_order_uav_devices ord LEFT JOIN vm_uav_device_info_t m on m.device_code = ord.device_code LEFT JOIN sys_area pro on pro.area_code = m.province_code LEFT JOIN sys_area city on city.area_code = m.city_code LEFT JOIN sys_area county on county.area_code = m.county_code LEFT JOIN sys_area town on town.area_code = m.town_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = m.device_code and rel.tenant_id = ord.tenant_id and rel.industry_code = ord.industry_code and rel.delete_flag = '0' and rel.device_type = 1 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '11' AND dct.user_id = #{param.userId} left join `vm_uav_nest_device_info` nest on m.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t nrel on nrel.device_code = nest.device_code and nrel.industry_code = ord.industry_code and nrel.tenant_id = ord.tenant_id and nrel.delete_flag = '0' and nrel.device_type = 4
LEFT JOIN vm_ar_tags_tree_user_rel art on art.coll_obj_code = m.device_code and art.coll_obj_type = '11' and art.user_id = #{param.userId}
WHERE m.delete_flag= '0' and ord.ord_status in (0, 1, 2) and ord.delete_flag= '0'
and ord.industry_code = #{param.industryCode}
and ord.tenant_id = #{param.tenantId}
and m.device_status != 2
and dct.user_device_coll_id IS NOT NULL
and m.device_type in
#{type}
and art.coll_obj_code IS NOT NULL
and m.device_status = #{param.deviceStatus}
and m.device_status in
#{item}
and m.uav_nest_code like CONCAT('%', #{param.uavNestCode}, '%')
and m.camera_model_code = #{param.cameraModelCode}
and m.uav_nest_code in
#{item}
and m.uav_nest_code is not null and m.uav_nest_code != ''
${param.dataScope} ORDER BY m.province_code, m.city_code, m.county_code, m.town_code, m.device_code

SELECT DISTINCT m.device_code as deviceCode, m.device_status, m.access_node, m.device_name, m.province_code as provinceId,pro.area_name as provinceName,m.city_code as cityId, city.area_name as cityName,m.county_code as countyId,county.area_name as countyName, m.town_code as townCode, town.area_name as townName, m.site_code, m.longitude,m.latitude, 'false' AS checked, '1' AS proLevel, '2' AS cityLevel,'3' AS countryLevel,'4' AS devLevel, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
case when IFNULL(art.id,0) = 0 then '0' else '1' end tagCollect,
(case when length(IFNULL(rel.device_name, '')) = 0 then m.device_name else rel.device_name end ) deviceAlias, nest.device_code uavNestCode, nest.altitude, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName, nest.resource_status uavNestStatus FROM vm_order_uav_devices ord LEFT JOIN vm_uav_device_info_t m on m.device_code = ord.device_code LEFT JOIN sys_area pro on pro.area_code = m.province_code LEFT JOIN sys_area city on city.area_code = m.city_code LEFT JOIN sys_area county on county.area_code = m.county_code LEFT JOIN sys_area town on town.area_code = m.town_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = m.device_code and rel.tenant_id = ord.tenant_id and rel.industry_code = ord.industry_code and rel.delete_flag = '0' and rel.device_type = 1 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '11' AND dct.user_id = #{param.userId} left join `vm_uav_nest_device_info` nest on m.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t nrel on nrel.device_code = nest.device_code and nrel.industry_code = ord.industry_code and nrel.tenant_id = ord.tenant_id and nrel.delete_flag = '0' and nrel.device_type = 4
LEFT JOIN vm_ar_tags_tree_user_rel art on art.coll_obj_code = m.device_code and art.coll_obj_type = '11' and art.user_id = #{param.userId}
WHERE m.delete_flag= '0' and ord.ord_status in (0, 1, 2) and ord.delete_flag= '0'
and ord.industry_code = #{param.industryCode}
and ord.tenant_id = #{param.tenantId}
and ord.accept_node = #{param.platformCode}
and m.device_status != 2
and dct.user_device_coll_id IS NOT NULL
and m.device_type in
#{type}
and art.coll_obj_code IS NOT NULL
and m.device_status = #{param.deviceStatus}
and m.device_status in
#{item}
and m.uav_nest_code like CONCAT('%', #{param.uavNestCode}, '%')
and m.camera_model_code = #{param.cameraModelCode}
and m.uav_nest_code in
#{item}
ORDER BY m.province_code, m.city_code, m.county_code, m.town_code, m.device_code

SELECT DISTINCT gg.dept_id as org_id, gg.dept_name as org_name, gg.dept_level as org_level, gg.parent_id as parent_org_id, dd.device_code, IFNULL(rel.device_name, de.device_name) AS device_name, concat(gg.dept_level + 1) AS devLevel, 'false' AS checked, de.longitude, de.latitude, 1 AS num, de.site_code,de.device_status, case when IFNULL(dct.user_device_coll_id, 0) = 0 then '0' else '1' end isMonitor, nest.device_code uavNestCode, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName, nest.resource_status uavNestStatus, nest.position_fix uavNestPositionFix, nest.calibration_status uavNestCalibrationStatus FROM sys_dept gg LEFT JOIN vm_organ_device_rel_t dd ON gg.dept_id = dd.dept_id and dd.device_type = 11 and gg.industry_code = dd.industry_code LEFT JOIN vm_uav_device_info_t de ON dd.device_code = de.device_code LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = de.device_code AND dct.coll_obj_type = '11' and dct.user_id = #{param.userId} left join vm_order_uav_devices vod on vod.industry_code = dd.industry_code and vod.device_code = de.device_code and vod.tenant_id = gg.tenant_id LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = vod.device_code and rel.tenant_id = vod.tenant_id and rel.industry_code = vod.industry_code and rel.delete_flag = '0' and rel.device_type = 1 left join `vm_uav_nest_device_info` nest on de.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t nrel on nrel.device_code = nest.device_code and nrel.industry_code = vod.industry_code and nrel.tenant_id = vod.tenant_id and nrel.delete_flag = '0' and nrel.device_type = 4 WHERE gg.del_flag = '0' AND dd.delete_flag = '0' AND de.delete_flag = '0' AND dd.device_code IS NOT NULL AND dd.device_code != '' AND vod.delete_flag = '0' AND vod.ord_status in (0,1,2)
and dct.user_device_coll_id IS NOT NULL
and de.device_status != 2
and de.device_type in
#{type}
and de.device_code in
#{item}
and de.device_status = #{param.deviceStatus}
and de.device_status in
#{item}
and de.uav_nest_code like CONCAT('%', #{param.uavNestCode}, '%')
and de.camera_model_code = #{param.cameraModelCode}
and de.uav_nest_code in
#{item}
${param.dataScope} ORDER BY gg.dept_id,dd.device_code

SELECT DISTINCT gg.dept_id as org_id, gg.dept_name as org_name, gg.dept_level as org_level, gg.parent_id as parent_org_id, dd.device_code, IFNULL(rel.device_name, de.device_name) AS device_name, concat(gg.dept_level + 1) AS devLevel, 'false' AS checked, de.longitude, de.latitude, 1 AS num, de.site_code,de.device_status, case when IFNULL(dct.user_device_coll_id, 0) = 0 then '0' else '1' end isMonitor, 'false' isNestDevice, nest.device_code uavNestCode, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName, nest.resource_status uavNestStatus, nest.position_fix uavNestPositionFix, nest.calibration_status uavNestCalibrationStatus FROM sys_dept gg LEFT JOIN vm_organ_device_rel_t dd ON gg.dept_id = dd.dept_id and dd.device_type = 11 and gg.industry_code = dd.industry_code LEFT JOIN vm_uav_device_info_t de ON dd.device_code = de.device_code LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = de.device_code AND dct.coll_obj_type = '11' and dct.user_id = #{param.userId} left join vm_order_uav_devices vod on vod.industry_code = dd.industry_code and vod.device_code = de.device_code and vod.tenant_id = gg.tenant_id LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = vod.device_code and rel.tenant_id = vod.tenant_id and rel.industry_code = vod.industry_code and rel.delete_flag = '0' and rel.device_type = 1 left join `vm_uav_nest_device_info` nest on de.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t nrel on nrel.device_code = nest.device_code and nrel.industry_code = vod.industry_code and nrel.tenant_id = vod.tenant_id and nrel.delete_flag = '0' and nrel.device_type = 4 WHERE gg.del_flag = '0' AND dd.delete_flag = '0' AND de.delete_flag = '0' AND dd.device_code IS NOT NULL AND dd.device_code != '' AND vod.delete_flag = '0' AND vod.ord_status in (0,1,2)
and dct.user_device_coll_id IS NOT NULL
and de.device_status != 2
and de.device_type in
#{type}
and de.device_status = #{param.deviceStatus}
and de.device_status in
#{item}
and de.uav_nest_code like CONCAT('%', #{param.uavNestCode}, '%')
and de.camera_model_code = #{param.cameraModelCode}
and de.uav_nest_code in
#{item}
${param.dataScope} ORDER BY gg.dept_id,dd.device_code

SELECT DISTINCT t2.site_code,t2.longitude,t2.latitude,t2.device_code as deviceCode, max(t2.hanging_height) as height, min(t2.device_status) as allLine FROM vm_order_uav_devices t1 left JOIN vm_uav_device_info_t t2 ON t1.device_code = t2.device_code WHERE t2.delete_flag = '0' AND t1.delete_flag = '0' and t1.ord_status in (0,1,2)
AND t2.city_code = #{param.cityId}
${param.dataScope} group by t2.site_code, t2.device_code

SELECT distinct dev.device_code, (case when length(IFNULL(tdr.device_name, '')) = 0 then dev.device_name else tdr.device_name end ) as device_name, dev.device_status, dev.uav_nest_code, nest.resource_status uavNestStatus, 'false' isNestDevice, ifnull(dev.hanging_height, 0) as height, dev.latitude, dev.longitude, dev.site_code FROM vm_uav_device_info_t dev left join vm_order_uav_devices t1 on dev.device_code = t1.device_code left join `vm_uav_nest_device_info` nest on dev.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t tdr on tdr.device_code = t1.device_code and tdr.tenant_id = t1.tenant_id and tdr.industry_code = t1.industry_code and tdr.delete_flag = 0 and tdr.device_type = 1 where dev.delete_flag = '0' AND t1.delete_flag = '0' AND t1.ord_status IN ( 0, 1, 2 )
AND dev.province_code = #{param.provinceId}
AND dev.city_code = #{param.cityId}
AND dev.county_code = #{param.countyId}
AND dev.town_code = #{param.townCode}
${param.dataScope}

SELECT distinct dev.device_code, (case when length(IFNULL(rel.device_name, '')) = 0 then dev.device_name else rel.device_name end) as device_name,
max(t2.hanging_height) as height, min(t2.device_status) as allLine,
ifnull(dev.hanging_height, 0) as height, dev.device_status as status,
dev.location, dev.latitude, dev.longitude, dev.site_code, dev.model_code,'false' isNestDevice, model.model_name model_name, nest.device_code uavNestCode, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName, nest.position_fix uavNestPositionFix, nest.calibration_status uavNestCalibrationStatus, nest.resource_status uavNestStatus FROM vm_uav_device_info_t dev left join vm_order_uav_devices t1 on dev.device_code = t1.device_code LEFT JOIN vm_uav_device_model_t model ON dev.model_code = model.model_code and model.delete_flag = 0 left join vm_tenant_device_common_rel_t rel ON rel.device_code = t1.device_code and rel.tenant_id = t1.tenant_id and rel.industry_code = t1.industry_code and rel.delete_flag = '0' and rel.device_type = 1 left join `vm_uav_nest_device_info` nest on dev.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t nrel on nrel.device_code = nest.device_code and nrel.industry_code = t1.industry_code and nrel.tenant_id = t1.tenant_id and nrel.delete_flag = '0' and nrel.device_type = 4 where t1.delete_flag = '0' and dev.delete_flag = '0' and t1.ord_status in (0,1,2)
AND dev.site_code = #{param.siteCode}
AND dev.latitude = #{param.latitude}
AND dev.longitude = #{param.longitude}
AND dev.city_code = #{param.cityId}
${param.dataScope}
group by t2.site_code, t2.device_code
order by dev.device_status,dev.device_code

select uavNest.deviceCode from (
select t.device_code deviceCode,
(case when length(IFNULL(rel.device_name, '')) = 0 then t.device_name else rel.device_name end ) deviceName
from `vm_uav_nest_device_info` t
LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = t.device_code
and rel.tenant_id = #{param.tenantId} and rel.industry_code = #{param.industryCode}
and rel.delete_flag = '0' and rel.device_type = 4
where t.delete_flag = 0

    AND t.manufacturer_code = #{param.uavNestManufacturerCode}


    AND t.model_code = #{param.uavNestModelCode}


    AND t.resource_status = #{param.uavNestStatus}



    AND t.resource_status = #{param.uavNestStatus}



    and t.resource_status in

        #{item}



) uavNest


        and uavNest.deviceName like CONCAT('%', #{param.uavNestName}, '%')

select camera_model_code
from vm_uav_device_info_t
where delete_flag = 0 and device_code = #{deviceCode}

mapper.update:
update vm_uav_device_info_t set province_code = #{param.provinceCode}, city_code = #{param.cityCode}, county_code = #{param.countyCode}, town_code = #{param.townCode}, location = #{param.address}, latitude = #{param.latitude}, longitude = #{param.longitude}, update_time = now() where uav_nest_code = #{param.deviceCode}
and device_code in
#{deviceCode}
and delete_flag = '0'

mapper.select:
SELECT DISTINCT m.device_code AS code, m.device_name AS name, m.device_name AS deviceName, m.device_status AS status, m.access_node AS accessNode, m.province_code AS provinceId, pro.area_name AS provinceName, m.city_code AS cityId, city.area_name AS cityName, m.county_code AS countyId, county.area_name AS countyName, m.town_code AS townCode, town.area_name AS townName, m.site_code AS siteCode, m.longitude, m.latitude, 'false' AS checked, '1' AS proLevel, '2' AS cityLevel, '3' AS countryLevel, '4' AS devLevel, CASE WHEN IFNULL(dct.user_device_coll_id, 0) = 0 THEN '0' ELSE '1' END isMonitor,
case when IFNULL(art.id,0) = 0 then '0' else '1' end as tagCollect,
(CASE WHEN length(IFNULL(rel.device_name, '')) = 0 THEN m.device_name ELSE rel.device_name END) deviceAlias, nest.device_code uavNestCode, nest.altitude, nest.longitude AS uavNestLongitude, nest.latitude AS uavNestLatitude, (CASE WHEN length(IFNULL(nrel.device_name, '')) = 0 THEN nest.device_name ELSE nrel.device_name END) uavNestName, nest.resource_status uavNestStatus, nest.position_fix nestPositionFix, nest.calibration_status uavNestCalibrationStatus, mount.uav_mount_model AS uavMountModel, 'false' as isNestDevice, null as uavNestPositionFix FROM vm_order_uav_devices ord LEFT JOIN vm_uav_device_info_t m ON m.device_code = ord.device_code LEFT JOIN ( SELECT device_code, GROUP_CONCAT(uav_mount_model) AS uav_mount_model FROM vm_uav_mount_model_rel_t WHERE delete_flag = 0 GROUP BY device_code ) mount ON mount.device_code = m.device_code LEFT JOIN sys_area pro ON pro.area_code = m.province_code LEFT JOIN sys_area city ON city.area_code = m.city_code LEFT JOIN sys_area county ON county.area_code = m.county_code LEFT JOIN sys_area town ON town.area_code = m.town_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = m.device_code AND rel.tenant_id = ord.tenant_id AND rel.industry_code = ord.industry_code AND rel.delete_flag = '0' AND rel.device_type = 1 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '11' AND dct.user_id = #{param.userId} LEFT JOIN `vm_uav_nest_device_info` nest ON m.uav_nest_code = nest.device_code LEFT JOIN vm_tenant_device_common_rel_t nrel ON nrel.device_code = nest.device_code AND nrel.industry_code = ord.industry_code AND nrel.tenant_id = ord.tenant_id AND nrel.delete_flag = '0' AND nrel.device_type = 4
LEFT JOIN vm_ar_tags_tree_user_rel art on art.coll_obj_code = m.device_code and art.coll_obj_type = '11' and art.user_id = #{param.userId}
WHERE m.delete_flag = '0' AND ord.ord_status IN (0, 1, 2) AND ord.delete_flag = '0'
AND ord.industry_code = #{param.industryCode}
AND ord.tenant_id = #{param.tenantId}
AND dct.user_device_coll_id IS NOT NULL
AND art.coll_obj_code IS NOT NULL
AND m.device_status in
#{item}
AND nest.resource_status in
#{item}
AND m.uav_nest_code in
#{item}
AND (m.device_code like concat('%',#{param.keywords},'%') or m.device_name like concat('%',#{param.keywords},'%'))
AND m.device_code in
#{item}
${param.dataScope}
UNION ALL
SELECT DISTINCT s.device_code AS code, NULL AS name, NULL AS deviceName, NULL AS status, NULL AS accessNode, s.province_code AS provinceId, pro2.area_name AS provinceName, s.city_code AS cityId, city2.area_name AS cityName, s.county_code AS countyId, county2.area_name AS countyName, s.town_code AS townCode, town2.area_name AS townName, null AS siteCode, null as longitude, null as latitude, 'false' AS checked, '1' AS proLevel, '2' AS cityLevel, '3' AS countryLevel, '4' AS devLevel, '0' AS isMonitor,
'0' AS tagCollect,
(CASE WHEN length(IFNULL(rel2.device_name, '')) = 0 THEN s.device_name ELSE rel2.device_name END) deviceAlias, s.device_code uavNestCode, s.altitude, s.longitude AS uavNestLongitude, s.latitude AS uavNestLatitude, (CASE WHEN length(IFNULL(rel2.device_name, '')) = 0 THEN s.device_name ELSE rel2.device_name END) uavNestName, s.resource_status uavNestStatus, s.position_fix nestPositionFix, s.calibration_status uavNestCalibrationStatus, NULL AS uavMountModel, 'true' as isNestDevice, s.position_fix as uavNestPositionFix FROM vm_order_uav_nest_devices z LEFT JOIN vm_uav_nest_device_info s ON z.device_code = s.device_code LEFT JOIN sys_area pro2 ON pro2.area_code = s.province_code LEFT JOIN sys_area city2 ON city2.area_code = s.city_code LEFT JOIN sys_area county2 ON county2.area_code = s.county_code LEFT JOIN sys_area town2 ON town2.area_code = s.town_code LEFT JOIN vm_tenant_device_common_rel_t rel2 ON rel2.device_code = s.device_code AND rel2.tenant_id = z.tenant_id AND rel2.industry_code = z.industry_code AND rel2.delete_flag = '0' AND rel2.device_type = 4 LEFT JOIN vm_user_device_collection_t dct2 ON dct2.coll_obj_code = s.device_code AND dct2.coll_obj_type = '11' AND dct2.user_id = #{param.userId}
LEFT JOIN vm_ar_tags_tree_user_rel art2 ON art2.coll_obj_code = s.device_code AND art2.coll_obj_type = '11' AND art2.user_id = #{param.userId}
WHERE z.device_code IN ( SELECT nest.device_code FROM vm_uav_nest_device_info AS nest LEFT JOIN vm_uav_device_info_t AS uav ON nest.device_code = uav.uav_nest_code and uav.delete_flag = 0 and uav.device_code in (SELECT device_code from vm_order_uav_devices where ord_status in (0,1,2)
AND industry_code = #{param.industryCode}
AND tenant_id = #{param.tenantId} ) WHERE uav.uav_nest_code IS NULL ) AND z.delete_flag = '0' and z.ord_status in (0,1,2)
AND z.industry_code = #{param.industryCode}
AND z.tenant_id = #{param.tenantId}
AND s.resource_status in
#{item}
AND s.device_code in
#{item}
AND (s.device_code like concat('%',#{param.keywords},'%') or s.device_name like concat('%',#{param.keywords},'%'))
${param.nestDataScope} ORDER BY provinceId, cityId, countyId, townCode, code

SELECT deviceCode, status, planTaskId, createTime FROM ( SELECT line.uav_code AS deviceCode, task.task_status AS status, task.plan_task_id AS planTaskId, task.create_time AS createTime, ROW_NUMBER() OVER ( PARTITION BY line.uav_code ORDER BY task.plan_time DESC ) AS rn FROM vm_air_line_t line LEFT JOIN vm_air_task_t task ON task.flight_route_id = line.flight_route_id AND task.delete_flag = '0' AND task.plan_time < #{currentTime} WHERE line.delete_flag = 0 AND line.uav_code IN
#{code}
) AS temp WHERE temp.rn = 1

SELECT deviceCode, planTime, planName FROM ( SELECT line.uav_code AS deviceCode, task.plan_time AS planTime, task.plan_name AS planName, ROW_NUMBER() OVER ( PARTITION BY line.uav_code ORDER BY task.plan_time ASC ) AS rn FROM vm_air_line_t line INNER JOIN vm_air_task_t task ON task.flight_route_id = line.flight_route_id AND task.delete_flag = '0' AND task.plan_time BETWEEN #{currentTime} AND #{endTime} WHERE line.delete_flag = 0 AND line.uav_code IN
#{code}
) AS temp WHERE temp.rn = 1

select count(dataTable.warning_order_id) from ${tableName} as dataTable
where dataTable.delete_flag = '0'
AND dataTable.task_record_id = #{planTaskId}
AND dataTable.tenant_id = #{tenantId}
AND dataTable.industry_code = #{industryCode}

SELECT model_code AS modelCode, model_name AS modelName, manufacturer_code AS manufacturerCode, mount_type AS mountType, support_function AS supportFunction FROM vm_uav_mount_model_t WHERE delete_flag = '0'
AND model_code IN
#{code}

SELECT deviceCode, planTime, planName FROM ( SELECT line.uav_code AS deviceCode, task.plan_time AS planTime, task.plan_name AS planName, ROW_NUMBER() OVER (PARTITION BY line.uav_code ORDER BY task.plan_time ASC) AS rn FROM vm_air_line_t line JOIN vm_air_task_t task ON task.flight_route_id = line.flight_route_id AND task.delete_flag = '0' WHERE line.delete_flag = 0 AND line.uav_code IN
#{code}
AND task.plan_time BETWEEN #{currentTime} AND #{endTime} ) tmp WHERE tmp.rn = 1;
